import{_ as i,l as d,o as a,c as s,v as t,p as c,x as o,d as n,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"特权级","description":"","frontmatter":{"title":"特权级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/privilege-rings.md","filePath":"cs/privilege-rings.md","lastUpdated":1789023840000}'),E={name:"cs/privilege-rings.md"};function h(m,e,S,C,u,_){const r=d("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="特权级" tabindex="-1">特权级 <a class="header-anchor" href="#特权级" aria-label="Permalink to &quot;特权级&quot;">​</a></h1><div class="epigraph"><p>用户程序不能随便写 `mtvec` 或关中断；硬件用特权级挡住这些 CSR 与指令，陷入时才升到能处理入口的那一层。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume II: Privileged Architecture 整理</footer></div><p>上一课<a href="/cs/plic-irq">PLIC 与中断号</a>钉死了保存 PC、跳到 <code>mtvec</code>。本课不重列 <code>mcause</code> 编码，也不从操作系统内核源码另起。缺口是：若用户指令也能写 <code>mtvec</code>、执行 <code>mret</code>、关全局中断，入口机制立刻被架空。必须把执行模式分成<strong>特权级</strong>，CSR 与某些指令只在足够高的级合法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 用户级子集没有模式。缺口是 RISC-V 的 M/S/U（教学可先 M 与 U）：当前级存在 CSR <code>mstatus</code> 等里。用户执行 <code>csrw mtvec</code> 或 <code>mret</code> 会非法指令异常。<code>ecall</code> 从 U 陷入 M（或 S），硬件升特权并关部分中断，入口代码才可信。返回 <code>mret</code>/<code>sret</code> 降特权、恢复 PC。</p><p>本课只钉「级」与「陷入升、返回降」。页表、用户/内核地址空间是体系结构与 OS 课；这里还没有虚存。组成课主干到此；下一课<a href="/cs/pipeline-five-stage">流水线五级</a>开始把单周期图切开重叠。</p><h3 id="特权级不是「环上的操作系统产品名」" tabindex="-1">特权级不是「环上的操作系统产品名」 <a class="header-anchor" href="#特权级不是「环上的操作系统产品名」" aria-label="Permalink to &quot;特权级不是「环上的操作系统产品名」&quot;">​</a></h3><p>x86 的 ring 0–3 是另一套编码；本栏用 RISC-V 的 M/S/U。不要把「Ring 0」当 RISC-V 术语。级也不等于进程：同一 U 级可以有许多进程，那是 OS 用页表造出来的，本课没有。</p><p><span class="marginnote">特权手册定义 M 必现，S 可选。Patterson/Hennessy 用用户/内核对照说明为何异常要换模式。本课不把 SELinux、虚拟化 H 扩展展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件维护当前特权。译码时检查指令是否允许：不允许则异常。陷入：保存先前级，当前级 ← 处理该陷阱的级（如 M）。<code>mret</code>：当前级 ← 保存的先前级。中断使能位按级屏蔽，避免入口未保存寄存器时再入。</p>',11)),(a(),c(p,null,{default:o(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22U%EF%BC%9A%E7%94%A8%E6%88%B7%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20ECALL%5B%22ecall%20%2F%20%E6%95%85%E9%9A%9C%20%2F%20%E4%B8%AD%E6%96%AD%22%5D%0A%20%20ECALL%20--%3E%20M%5B%22M%EF%BC%9A%E5%85%A5%E5%8F%A3%E4%B8%8E%20CSR%22%5D%0A%20%20M%20--%3E%20MRET%5B%22mret%20%E9%99%8D%E5%9B%9E%20U%22%5D%0A%20%20MRET%20--%3E%20U%0A%20%20M%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B5%81%E6%B0%B4%E7%BA%BF%E9%87%8D%E5%8F%A0%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了级，存储程序机器才分得出「普通加法」与「改入口向量」。后课内核/用户态是本课在 OS 里的名字；系统调用路径 = <code>ecall</code> + 本课升级。设备 MMIO 也可以只在 M 可访问，本课只要求检查存在。</p><p>组成课不把流水线冒险算进特权：特权是状态，流水线是执行重叠。两者在「流水线异常」叶子才会交汇。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现分页、不讲 TEE、不把安全栏的沙箱提前。虚拟机监控的两层翻译是更后的附录或 OS/体系交界。数字逻辑与计算机组成课程到此收束：能跑带陷阱的 RISC-V 整数核、分用户与机器模式。</p><p>后课默认：用户代码在 U，陷阱在更高特权处理。下一起点是：一条指令仍太慢，要用五级流水重叠。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>特权级限制 CSR 与 <code>mret</code> 等指令；陷入升、<code>mret</code> 降。</li><li>用户不能改自己的陷阱入口。</li><li>组成主干停在可编程、可陷阱、分模式的 RISC-V 核；流水线是下一课程。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V Privileged Spec。</li></ul>',8))])}const B=i(E,[["render",h]]);export{f as __pageData,B as default};
